/**
 * ARExplorer - 增强现实探索模块
 * AR工具预览 + 3D模型展示 + 交互体验
 */

// AR状态
const AR_STATE_KEY = 'ai-creator-ar-state';

// AR功能检测
export function isARSupported() {
  return !!(navigator.xr || navigator.mediaDevices?.getUserMedia);
}

// 获取AR状态
export function getARState() {
  try {
    const stored = localStorage.getItem(AR_STATE_KEY);
    if (!stored) return getDefaultARState();
    return JSON.parse(stored);
  } catch {
    return getDefaultARState();
  }
}

// 保存AR状态
function saveARState(state) {
  try {
    localStorage.setItem(AR_STATE_KEY, JSON.stringify(state));
  } catch {}
}

// 默认AR状态
function getDefaultARState() {
  return {
    enabled: true,
    quality: 'medium',
    showGuide: true,
    lastUsed: null
  };
}

// 更新AR状态
export function updateARState(updates) {
  const state = getARState();
  const merged = { ...state, ...updates, lastUsed: Date.now() };
  saveARState(merged);
  return merged;
}

