// ============ 3D渲染引擎（简化版）==========

/**
 * 创建AR画布容器
 */
export function createARCanvas(container, options = {}) {
  const {
    width = 320,
    height = 240,
    backgroundColor = '#0f0f1a'
  } = options;
  
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  canvas.style.cssText = `
    width: 100%;
    height: 100%;
    border-radius: 8px;
    background: ${backgroundColor};
  `;
  
  container.appendChild(canvas);
  
  const ctx = canvas.getContext('2d');
  let animationId = null;
  let currentTool = null;
  let phase = 0;
  
  // 绘制工具3D效果
  function drawTool(config, time) {
    const centerX = width / 2;
    const centerY = height / 2;
    
    // 清空画布
    ctx.fillStyle = backgroundColor;
    ctx.fillRect(0, 0, width, height);
    
    // 绘制背景网格
    ctx.strokeStyle = '#ffffff08';
    ctx.lineWidth = 1;
    const gridSize = 20;
    for (let x = 0; x < width; x += gridSize) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, height);
      ctx.stroke();
    }
    for (let y = 0; y < height; y += gridSize) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(width, y);
      ctx.stroke();
    }
    
    // 动画相位
    const t = time / 1000;
    const floatY = Math.sin(t * 2) * 10;
    const pulseScale = 1 + Math.sin(t * 3) * 0.1;
    const rotateAngle = t * 0.5;
    
    ctx.save();
    ctx.translate(centerX, centerY + floatY);
    
    // 根据动画类型应用变换
    if (config.animation === 'pulse') {
      ctx.scale(pulseScale, pulseScale);
    } else if (config.animation === 'rotate') {
      ctx.rotate(rotateAngle);
    }
    
    // 绘制3D效果
    const size = 60 * (config.scale || 1);
    const color = config.previewColor || '#8b5cf6';
    
    // 绘制阴影
    ctx.fillStyle = '#00000040';
    ctx.beginPath();
    ctx.ellipse(0, size * 0.6, size * 0.6, size * 0.15, 0, 0, Math.PI * 2);
    ctx.fill();
    
    // 绘制主体
    const gradient = ctx.createRadialGradient(0, 0, 0, 0, 0, size);
    gradient.addColorStop(0, color);
    gradient.addColorStop(0.7, adjustColor(color, -30));
    gradient.addColorStop(1, adjustColor(color, -60));
    
    ctx.fillStyle = gradient;
    ctx.beginPath();
    
    if (config.type === 'diagram') {
      // 绘制流程图样式
      drawFlowDiagram(ctx, size, color, t);
    } else {
      // 绘制3D球体
      drawSphere(ctx, size, gradient);
    }
    
    ctx.restore();
    
    // 绘制光晕
    const glowSize = size * 1.5 * (1 + Math.sin(t * 2) * 0.2);
    const glowGradient = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, glowSize);
    glowGradient.addColorStop(0, color + '30');
    glowGradient.addColorStop(0.5, color + '10');
    glowGradient.addColorStop(1, 'transparent');
    
    ctx.fillStyle = glowGradient;
    ctx.fillRect(0, 0, width, height);
    
    // 绘制标签
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 12px system-ui';
    ctx.textAlign = 'center';
    ctx.fillText(config.description || 'AR Preview', centerX, height - 20);
    
    // 绘制AR标记
    drawARMarkers(ctx, centerX, centerY, size, t);
  }
  
  function drawSphere(ctx, size, gradient) {
    // 球体
    ctx.beginPath();
    ctx.arc(0, 0, size, 0, Math.PI * 2);
    ctx.fill();
    
    // 高光
    const highlightGradient = ctx.createRadialGradient(
      -size * 0.3, -size * 0.3, 0,
      -size * 0.3, -size * 0.3, size * 0.5
    );
    highlightGradient.addColorStop(0, 'rgba(255,255,255,0.4)');
    highlightGradient.addColorStop(1, 'rgba(255,255,255,0)');
    
    ctx.fillStyle = highlightGradient;
    ctx.beginPath();
    ctx.arc(0, 0, size, 0, Math.PI * 2);
    ctx.fill();
    
    // 边缘光
    ctx.strokeStyle = 'rgba(255,255,255,0.2)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(0, 0, size, 0, Math.PI * 2);
    ctx.stroke();
  }
  
  function drawFlowDiagram(ctx, size, color, t) {
    const nodes = [
      { x: -size * 0.5, label: '输入' },
      { x: 0, label: '处理' },
      { x: size * 0.5, label: '输出' }
    ];
    
    // 连线
    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(nodes[0].x + 20, 0);
    ctx.lineTo(nodes[1].x - 20, 0);
    ctx.moveTo(nodes[1].x + 20, 0);
    ctx.lineTo(nodes[2].x - 20, 0);
    ctx.stroke();
    
    // 流动点
    const flowPos = (t * 50) % 60 - 20;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(nodes[1].x + flowPos, 0, 5, 0, Math.PI * 2);
    ctx.fill();
    
    // 节点
    for (const node of nodes) {
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.roundRect(node.x - 20, -15, 40, 30, 6);
      ctx.fill();
      
      ctx.fillStyle = '#ffffff';
      ctx.font = '10px system-ui';
      ctx.textAlign = 'center';
      ctx.fillText(node.label, node.x, 3);
    }
  }
  
  function drawARMarkers(ctx, cx, cy, size, t) {
    const corners = [
      { x: 20, y: 20 },
      { x: width - 20, y: 20 },
      { x: 20, y: height - 20 },
      { x: width - 20, y: height - 20 }
    ];
    
    ctx.strokeStyle = '#60a5fa';
    ctx.lineWidth = 2;
    
    for (const corner of corners) {
      const offset = Math.sin(t * 3) * 2;
      ctx.beginPath();
      ctx.moveTo(corner.x, corner.y + 10 + offset);
      ctx.lineTo(corner.x, corner.y + offset);
      ctx.lineTo(corner.x + 10, corner.y + offset);
      ctx.stroke();
    }
    
    // AR标签
    ctx.fillStyle = '#60a5fa';
    ctx.font = '9px system-ui';
    ctx.textAlign = 'left';
    ctx.fillText('AR', 20, 15);
    ctx.textAlign = 'right';
    ctx.fillText('AI-CREATOR', width - 20, 15);
  }
  
  function adjustColor(hex, amount) {
    const num = parseInt(hex.slice(1), 16);
    const r = Math.min(255, Math.max(0, (num >> 16) + amount));
    const g = Math.min(255, Math.max(0, ((num >> 8) & 0x00FF) + amount));
    const b = Math.min(255, Math.max(0, (num & 0x0000FF) + amount));
    return `#${((r << 16) | (g << 8) | b).toString(16).padStart(6, '0')}`;
  }
  
  // 启动渲染循环
  function startRender(toolId) {
    currentTool = toolId;
    const config = getToolARConfig(toolId);
    
    function render(time) {
      drawTool(config, time);
      animationId = requestAnimationFrame(render);
    }
    
    animationId = requestAnimationFrame(render);
  }
  
  // 停止渲染
  function stopRender() {
    if (animationId) {
      cancelAnimationFrame(animationId);
      animationId = null;
    }
    currentTool = null;
  }
  
  // 清理
  function dispose() {
    stopRender();
    canvas.remove();
  }
  
  return {
    canvas,
    startRender,
    stopRender,
    dispose
  };
}

/**
 * 创建AR交互层
 */
export function createARInteractionLayer(container, options = {}) {
  const {
    onTap,
    onSwipe
  } = options;
  
  let startX = 0;
  let startY = 0;
  let lastTap = 0;
  
  function handleTouchStart(e) {
    const touch = e.touches[0];
    startX = touch.clientX;
    startY = touch.clientY;
  }
  
  function handleTouchEnd(e) {
    const touch = e.changedTouches[0];
    const deltaX = touch.clientX - startX;
    const deltaY = touch.clientY - startY;
    const now = Date.now();
    
    // 检测点击
    if (Math.abs(deltaX) < 10 && Math.abs(deltaY) < 10) {
      if (now - lastTap < 300) {
        // 双击
        onTap?.({ x: touch.clientX, y: touch.clientY, type: 'double-tap' });
      } else {
        // 单击
        onTap?.({ x: touch.clientX, y: touch.clientY, type: 'tap' });
      }
      lastTap = now;
    }
    
    // 检测滑动
    if (Math.abs(deltaX) > 50) {
      onSwipe?.({ direction: deltaX > 0 ? 'right' : 'left', deltaX });
    }
    if (Math.abs(deltaY) > 50) {
      onSwipe?.({ direction: deltaY > 0 ? 'down' : 'up', deltaY });
    }
  }
  
  container.addEventListener('touchstart', handleTouchStart, { passive: true });
  container.addEventListener('touchend', handleTouchEnd, { passive: true });
  
  function dispose() {
    container.removeEventListener('touchstart', handleTouchStart);
    container.removeEventListener('touchend', handleTouchEnd);
  }
  
  return { dispose };
}

export default {
  isARSupported,
  getARState,
  updateARState,
  getToolARConfig,
  createARCanvas,
  createARInteractionLayer
};