/**
 * ARExplorerPanel - 增强现实探索面板
 */
import {
  isARSupported,
  getARState,
  updateARState,
  getToolARConfig,
  createARCanvas,
  createARInteractionLayer
} from './ARExplorer.js';
import { toolRegistry } from './registry.js';

export function createARExplorerPanel() {
  const panel = document.createElement('div');
  panel.id = 'ar-panel';
  
  const arState = getARState();
  const supported = isARSupported();
  
  let currentTool = null;
  let arRenderer = null;
  let interactionLayer = null;
  
  function render() {
    const tools = Object.keys(toolRegistry).slice(0, 12);
    
    let content = '<div class="ar-header">' +
      '<span class="ar-title">🔮 AR探索</span>' +
      '<button class="ar-close" data-action="close">×</button>' +
    '</div>' +
    '<div class="ar-body">';
    
    // AR状态
    content += '<div class="ar-section">' +
      '<div class="ar-status ' + (supported ? 'supported' : 'unsupported') + '">' +
        '<span class="ar-status-icon">' + (supported ? '✓' : '✗') + '</span>' +
        '<span class="ar-status-text">' + (supported ? 'AR功能可用' : 'AR功能受限') + '</span>' +
      '</div>' +
    '</div>';
    
    // AR预览区
    content += '<div class="ar-section">' +
      '<div class="ar-section-title">🖼️ 实时预览</div>' +
      '<div class="ar-preview-container" id="ar-preview-container">' +
        '<div class="ar-preview-placeholder">' +
          '<span>选择下方工具查看AR效果</span>' +
        '</div>' +
      '</div>' +
      '<div class="ar-preview-info" id="ar-preview-info">' +
        '<span>点击画布交互，双击放大</span>' +
      '</div>' +
    '</div>';
    
    // 工具选择
    content += '<div class="ar-section">' +
      '<div class="ar-section-title">🧰 工具AR效果</div>' +
      '<div class="ar-tools-grid">';
    
    for (const toolId of tools) {
      const config = getToolARConfig(toolId);
      const isActive = currentTool === toolId;
      
      content += '<div class="ar-tool-card ' + (isActive ? 'active' : '') + '" data-tool="' + toolId + '">' +
        '<div class="ar-tool-icon" style="background: ' + config.previewColor + '20; color: ' + config.previewColor + '">' +
          getToolIcon(toolId) +
        '</div>' +
        '<div class="ar-tool-name">' + toolId.replace(/-/g, ' ') + '</div>' +
        '<div class="ar-tool-animation">' + config.animation + '</div>' +
      '</div>';
    }
    
    content += '</div></div>';
    
    // AR设置
    content += '<div class="ar-section">' +
      '<div class="ar-section-title">⚙️ AR设置</div>' +
      
      '<div class="ar-setting-item">' +
        '<div class="ar-setting-info">' +
          '<div class="ar-setting-label">启用AR</div>' +
          '<div class="ar-setting-desc">在工具预览中显示AR效果</div>' +
        '</div>' +
        '<label class="ar-switch">' +
          '<input type="checkbox" id="ar-enabled" ' + (arState.enabled ? 'checked' : '') + '>' +
          '<span class="ar-slider"></span>' +
        '</label>' +
      '</div>' +
      
      '<div class="ar-setting-item">' +
        '<div class="ar-setting-label">显示引导</div>' +
        '<label class="ar-switch">' +
          '<input type="checkbox" id="ar-guide" ' + (arState.showGuide ? 'checked' : '') + '>' +
          '<span class="ar-slider"></span>' +
        '</label>' +
      '</div>' +
      
      '<div class="ar-setting-item">' +
        '<div class="ar-setting-label">质量</div>' +
        '<select id="ar-quality" class="ar-select">' +
          '<option value="low" ' + (arState.quality === 'low' ? 'selected' : '') + '>低</option>' +
          '<option value="medium" ' + (arState.quality === 'medium' ? 'selected' : '') + '>中</option>' +
          '<option value="high" ' + (arState.quality === 'high' ? 'selected' : '') + '>高</option>' +
        '</select>' +
      '</div>' +
      
    '</div>';
    
    content += '</div>';
    
    panel.innerHTML = content;
    
    // 绑定事件
    panel.querySelector('[data-action="close"]').addEventListener('click', () => panel.remove());
    panel.addEventListener('click', (e) => e.stopPropagation());
    
    // 工具选择
    panel.querySelectorAll('.ar-tool-card').forEach(card => {
      card.addEventListener('click', function() {
        const toolId = this.dataset.tool;
        selectTool(toolId);
      });
    });
    
    // AR设置开关
    panel.querySelector('#ar-enabled')?.addEventListener('change', function() {
      updateARState({ enabled: this.checked });
    });
    
    panel.querySelector('#ar-guide')?.addEventListener('change', function() {
      updateARState({ showGuide: this.checked });
    });
    
    panel.querySelector('#ar-quality')?.addEventListener('change', function() {
      updateARState({ quality: this.value });
    });
  }
  
  function selectTool(toolId) {
    currentTool = toolId;
    
    // 更新UI
    panel.querySelectorAll('.ar-tool-card').forEach(card => {
      card.classList.toggle('active', card.dataset.tool === toolId);
    });
    
    // 启动AR渲染
    const container = panel.querySelector('#ar-preview-container');
    if (!container) return;
    
    // 清理旧的
    if (arRenderer) {
      arRenderer.dispose();
      arRenderer = null;
    }
    if (interactionLayer) {
      interactionLayer.dispose();
      interactionLayer = null;
    }
    
    // 清空容器
    container.innerHTML = '';
    
    // 创建AR画布
    arRenderer = createARCanvas(container, {
      width: 300,
      height: 200,
      backgroundColor: '#0f0f1a'
    });
    
    // 启动渲染
    arRenderer.startRender(toolId);
    
    // 创建交互层
    interactionLayer = createARInteractionLayer(container, {
      onTap: (info) => {
        showTapEffect(info.x, info.y);
        if (info.type === 'double-tap') {
          toggleFullscreen();
        }
      },
      onSwipe: (info) => {
        // 切换工具
        const tools = Object.keys(toolRegistry).slice(0, 12);
        const currentIdx = tools.indexOf(currentTool);
        let nextIdx;
        if (info.direction === 'left') {
          nextIdx = (currentIdx + 1) % tools.length;
        } else if (info.direction === 'right') {
          nextIdx = (currentIdx - 1 + tools.length) % tools.length;
        }
        if (nextIdx !== undefined) {
          selectTool(tools[nextIdx]);
        }
      }
    });
    
    // 更新信息
    const info = panel.querySelector('#ar-preview-info');
    if (info) {
      info.innerHTML = '<span>双击放大 · 左右滑动切换工具</span>';
    }
  }
  
  function showTapEffect(x, y) {
    const container = panel.querySelector('#ar-preview-container');
    if (!container) return;
    
    const rect = container.getBoundingClientRect();
    const effect = document.createElement('div');
    effect.className = 'ar-tap-effect';
    effect.style.cssText = `
      position: absolute;
      left: ${x - rect.left}px;
      top: ${y - rect.top}px;
      width: 40px;
      height: 40px;
      margin: -20px 0 0 -20px;
      border-radius: 50%;
      border: 2px solid #60a5fa;
      animation: ar-tap 0.6s ease-out forwards;
      pointer-events: none;
    `;
    container.appendChild(effect);
    
    setTimeout(() => effect.remove(), 600);
  }
  
  function toggleFullscreen() {
    const container = panel.querySelector('#ar-preview-container');
    if (!container) return;
    
    if (document.fullscreenElement) {
      document.exitFullscreen();
    } else {
      container.requestFullscreen?.();
    }
  }
  
  function getToolIcon(toolId) {
    const icons = {
      'image-generator': '🎨',
      'music-generator': '🎵',
      'tts-service': '🗣️',
      'workflow': '⚡',
      'default': '🔧'
    };
    return icons[toolId] || icons['default'];
  }
  
  // Styles
  const style = document.createElement('style');
  style.id = 'ar-panel-style';
  style.textContent = [
    '#ar-panel {',
      'position: fixed; top: 50%; left: 50%; transform: translate(-50%,-50%);',
      'width: 480px; max-height: 85vh; background: #1a1a2e; border: 1px solid #333;',
      'border-radius: 12px; box-shadow: 0 20px 60px rgba(0,0,0,0.5);',
      'z-index: 1017; font-family: system-ui, sans-serif; display: flex; flex-direction: column;',
    '}',
    '.ar-header {',
      'display: flex; justify-content: space-between; align-items: center;',
      'padding: 14px 16px; border-bottom: 1px solid #333;',
      'background: #16162a; border-radius: 12px 12px 0 0;',
    '}',
    '.ar-title { font-size: 15px; font-weight: 600; color: #a78bfa; }',
    '.ar-close { background: none; border: none; color: #888; font-size: 20px; cursor: pointer; }',
    '.ar-body { flex: 1; overflow-y: auto; padding: 12px; }',
    '.ar-section { margin-bottom: 16px; }',
    '.ar-section-title {',
      'font-size: 11px; font-weight: 600; color: #888; text-transform: uppercase;',
      'margin-bottom: 10px; letter-spacing: 0.5px;',
    '}',
    '.ar-status {',
      'display: flex; align-items: center; gap: 8px; padding: 10px 12px;',
      'border-radius: 8px; font-size: 13px;',
    '}',
    '.ar-status.supported { background: #10b98122; color: #10b981; }',
    '.ar-status.unsupported { background: #888822; color: #888; }',
    '.ar-status-icon { font-size: 16px; }',
    '.ar-preview-container {',
      'position: relative; height: 200px; background: #0f0f1a; border-radius: 8px;',
      'overflow: hidden; display: flex; align-items: center; justify-content: center;',
    '}',
    '.ar-preview-placeholder {',
      'text-align: center; color: #666; font-size: 13px;',
    '}',
    '.ar-preview-info {',
      'text-align: center; font-size: 11px; color: #666; margin-top: 8px;',
    '}',
    '.ar-tools-grid {',
      'display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px;',
    '}',
    '.ar-tool-card {',
      'padding: 10px 6px; background: #12122a; border-radius: 8px;',
      'text-align: center; cursor: pointer; border: 2px solid transparent;',
      'transition: border-color 0.2s, transform 0.2s;',
    '}',
    '.ar-tool-card:hover { transform: scale(1.02); }',
    '.ar-tool-card.active { border-color: #a78bfa; }',
    '.ar-tool-icon {',
      'font-size: 24px; width: 40px; height: 40px; border-radius: 8px;',
      'display: flex; align-items: center; justify-content: center; margin: 0 auto 6px;',
    '}',
    '.ar-tool-name {',
      'font-size: 9px; color: #888; text-transform: capitalize;',
      'white-space: nowrap; overflow: hidden; text-overflow: ellipsis;',
    '}',
    '.ar-tool-animation {',
      'font-size: 8px; color: #666; margin-top: 2px;',
    '}',
    '.ar-setting-item {',
      'display: flex; justify-content: space-between; align-items: center;',
      'padding: 8px 0; border-bottom: 1px solid #222;',
    '}',
    '.ar-setting-label { font-size: 13px; color: #fff; }',
    '.ar-setting-desc { font-size: 11px; color: #666; }',
    '.ar-switch {',
      'position: relative; width: 44px; height: 24px; cursor: pointer;',
    '}',
    '.ar-switch input { opacity: 0; width: 0; height: 0; }',
    '.ar-slider {',
      'position: absolute; top: 0; left: 0; right: 0; bottom: 0;',
      'background: #333; border-radius: 12px; transition: 0.2s;',
    '}',
    '.ar-slider:before {',
      'position: absolute; content: ""; height: 18px; width: 18px;',
      'left: 3px; bottom: 3px; background: white; border-radius: 50%; transition: 0.2s;',
    '}',
    'input:checked + .ar-slider { background: #a78bfa; }',
    'input:checked + .ar-slider:before { transform: translateX(20px); }',
    '.ar-select {',
      'padding: 6px 10px; background: #12122a; border: 1px solid #333;',
      'border-radius: 6px; color: #fff; font-size: 12px; cursor: pointer;',
    '}',
    '@keyframes ar-tap {',
      '0% { transform: scale(0); opacity: 1; }',
      '100% { transform: scale(2); opacity: 0; }',
    '}',
  ].join('');
  
  if (!document.getElementById('ar-panel-style')) {
    document.head.appendChild(style);
  }
  
  render();
  
  panel.querySelector('[data-action="close"]').addEventListener('click', () => {
    if (arRenderer) arRenderer.dispose();
    if (interactionLayer) interactionLayer.dispose();
    panel.remove();
  });
  panel.addEventListener('click', (e) => e.stopPropagation());
  
  return panel;
}